/*
 * ULTRA-WIDEBAND (UWB) POSITIONING NETWORK
 * UWA  ceiling anchors [id, x, y] in map units (10 units = 1 m). UWO  obstructions that weaken
 *      UWB signals: metal racking, dry cabinets and the quarantine cage mesh, each with an extra
 *      path-loss weight per unit crossed.
 * uwbGrid() samples the floor every 1 m. For each point it counts the online anchors whose
 * effective distance (straight-line distance plus obstruction penalty) is inside UWR. Time-difference
 * positioning needs 3 anchors for a 2D fix and 4 or more for a precise one. Points with fewer than
 * 3 anchors are gaps, and touching gap cells are grouped into named gap areas with a suggested
 * anchor position. The result is cached until the set of offline anchors or the theme changes.
 */
const UWA=[['U-01',10,12],['U-02',150,12],['U-03',330,14],['U-04',520,14],['U-05',690,14],['U-06',770,118],['U-07',770,300],['U-08',700,404],['U-09',470,404],['U-10',250,404],['U-11',10,240],['U-12',10,400],['U-13',268,153],['U-14',470,153],['U-15',164,300],['U-16',584,236]],
  UWO=[{x:182,y:40,w:380,h:40,k:3.2},{x:182,y:102,w:380,h:40,k:3.2},{x:182,y:164,w:380,h:40,k:3.2},{x:182,y:226,w:380,h:40,k:3.2},{x:602,y:36,w:170,h:56,k:2.6},{x:594,y:126,w:184,h:100,k:1.4}],
  UWR=300,UWZ=[['Receiving',2,26,64,350],['IQC',76,26,86,200],['Main storage',172,26,400,270],['Dry storage',594,26,184,76],['Quarantine cage',594,126,184,100],['Line-side kitting',172,322,400,70],['Shipping',594,250,184,142]];
const uwbZone=(x,y)=>{const z=UWZ.find(z=>x>=z[1]&&x<=z[1]+z[3]&&y>=z[2]&&y<=z[2]+z[4]);return z?z[0]:'Cross aisles'};
function uwbLink(a,x,y){const dx=x-a[1],dy=y-a[2],d=Math.hypot(dx,dy);if(d>UWR)return 0;let pen=0;const n=Math.ceil(d/4);
  for(let i=1;i<n;i++){const px=a[1]+dx*i/n,py=a[2]+dy*i/n;for(const o of UWO)if(px>=o.x&&px<=o.x+o.w&&py>=o.y&&py<=o.y+o.h){pen+=(d/n)*o.k;break}}
  const e=d+pen;return e<UWR?1-e/UWR:0}
function uwbGrid(){const css=getComputedStyle(document.documentElement),cv=k=>css.getPropertyValue(k).trim(),key=[...WA.uwbOff].sort().join()+'|'+cv('--g')+cv('--r');if(WA.ug&&WA.ug.k===key)return WA.ug;
  const W=78,H=41,L=new Uint8Array(W*H),Q=new Float32Array(W*H),on=UWA.filter(a=>!WA.uwbOff.has(a[0])),cov={};on.forEach(a=>cov[a[0]]=0);
  for(let j=0;j<H;j++)for(let i=0;i<W;i++){const x=i*10+5,y=j*10+5,qs=[];on.forEach(a=>{const q=uwbLink(a,x,y);if(q>0){qs.push(q);cov[a[0]]++}});qs.sort((p,q)=>q-p);L[j*W+i]=Math.min(9,qs.length);Q[j*W+i]=qs.slice(0,4).reduce((s,q)=>s+q,0)}
  const hex=h=>{h=h.replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');return[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)||0)},G=hex(cv('--g')),Y=hex(cv('--y')),O=hex(cv('--o')),R=hex(cv('--r'));
  const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d'),im=x.createImageData(W,H);
  for(let k=0;k<W*H;k++){const l=L[k],col=l>=4?G:l===3?Y:l===2?O:R,al=l>=4?Math.round(60+Math.min(1,Q[k]/2.4)*60):l===3?120:l===2?150:175;im.data.set([col[0],col[1],col[2],al],k*4)}
  x.putImageData(im,0,0);
  const seen=new Uint8Array(W*H),gaps=[];
  for(let k=0;k<W*H;k++){if(seen[k]||L[k]>=3)continue;const st=[k],cells=[];seen[k]=1;while(st.length){const p=st.pop();cells.push(p);const i=p%W,j=(p-i)/W;[[1,0],[-1,0],[0,1],[0,-1]].forEach(d=>{const a=i+d[0],b=j+d[1],q=b*W+a;if(a>=0&&a<W&&b>=0&&b<H&&!seen[q]&&L[q]<3){seen[q]=1;st.push(q)}})}
    if(cells.length<3)continue;const set=new Set(cells);let path='',sx=0,sy=0,mn=9;cells.forEach(p=>{const i=p%W,j=(p-i)/W,X=i*10,Y2=j*10;sx+=X+5;sy+=Y2+5;mn=Math.min(mn,L[p]);
      if(!set.has(p-W)||j===0)path+='M'+X+' '+Y2+'h10';if(!set.has(p+W)||j===H-1)path+='M'+X+' '+(Y2+10)+'h10';if(!set.has(p-1)||i===0)path+='M'+X+' '+Y2+'v10';if(!set.has(p+1)||i===W-1)path+='M'+(X+10)+' '+Y2+'v10'});
    const cx=sx/cells.length,cy=sy/cells.length;gaps.push({n:'G-'+(gaps.length+1),area:cells.length,min:mn,cx:cx,cy:cy,zone:uwbZone(cx,cy),path:path})}
  gaps.sort((a,b)=>b.area-a.area);gaps.forEach((g,i)=>g.n='G-'+(i+1));
  const cnt=[0,0,0,0];for(let k=0;k<W*H;k++)cnt[L[k]>=4?0:L[k]===3?1:L[k]===2?2:3]++;
  WA.ug={k:key,W:W,H:H,L:L,url:c.toDataURL(),gaps:gaps,cnt:cnt,tot:W*H,cov:cov};return WA.ug}
const uwbAt=(x,y)=>{const g=uwbGrid(),i=clamp(Math.floor(x/10),0,g.W-1),j=clamp(Math.floor(y/10),0,g.H-1);return g.L[j*g.W+i]},
  uwbAcc=l=>l>=4?['\u00b10.3 m','g',3]:l===3?['\u00b10.8 m','y',7]:l===2?['1D only','o',12]:['no fix','r',0];
/*
 * uwbOv(): heat map image, gap outlines with labels, anchors with radio pulses, and the legend.
 */
function uwbOv(lb){const g=uwbGrid();let s='<image href="'+g.url+'" x="0" y="0" width="780" height="410" preserveAspectRatio="none" style="image-rendering:auto"/>';
  g.gaps.forEach(q=>{s+='<path d="'+q.path+'" style="fill:none;stroke:var(--r);stroke-width:1.6;stroke-dasharray:4 3;stroke-dashoffset:'+(-WA.t*8%7).toFixed(2)+';opacity:.95"/>'});
  g.gaps.forEach(q=>{if(q.area>=6)s+=wmPill(q.cx,q.cy,q.n+' '+(q.min<=1?'no fix':'weak')+', '+q.area+' m\u00b2','r',7.5,lb)});
  UWA.forEach((a,i)=>{const off=WA.uwbOff.has(a[0]),p=(WA.t*.6+i*.137)%1;
    if(!off)s+='<circle cx="'+a[1]+'" cy="'+a[2]+'" r="'+(6+p*44).toFixed(1)+'" style="fill:none;stroke:var(--c);stroke-width:1.2;opacity:'+((1-p)*.55).toFixed(2)+'"/>';
    s+='<g transform="translate('+a[1]+' '+a[2]+')"><path d="M0 -6L6 0L0 6L-6 0Z" style="fill:'+(off?'var(--pn2)':'var(--c)')+';stroke:'+(off?'var(--r)':'var(--tx)')+';stroke-width:1.2"/>'+(off?'<path d="M-3 -3L3 3M3 -3L-3 3" style="stroke:var(--r);stroke-width:1.4"/>':'<circle r="1.6" style="fill:var(--pn)"/>')+'</g>';
    const ty=a[2]<30?a[2]+15:a[2]-10;s+='<text x="'+clamp(a[1],18,762)+'" y="'+ty+'" text-anchor="middle" style="font-size:7px;font-weight:700;fill:var(--'+(off?'r':'tx')+');paint-order:stroke;stroke:var(--pn);stroke-width:2.5px">'+a[0]+(off?' offline':'')+'</text>'});
  let x=448;s+='<text x="'+x+'" y="405" style="font-size:9px;font-weight:700;fill:var(--mu)">UWB anchors in view</text>';x+=104;
  [['g','4+ precise'],['y','3 fix'],['o','2 weak'],['r','0-1 gap']].forEach(l=>{s+='<rect x="'+x+'" y="398.5" width="12" height="7" rx="2" style="fill:var(--'+l[0]+');opacity:.8"/><text x="'+(x+15)+'" y="405" style="font-size:9px;fill:var(--mu)">'+l[1]+'</text>';x+=l[1].length*4.6+24});
  return s}
/*
 * uwbReport(): coverage breakdown, gap areas with a suggested anchor position, and each anchor
 * with the floor area it reaches. Anchors can be taken offline to see the effect of an outage.
 */
function uwbReport(){const g=uwbGrid(),pc=i=>(g.cnt[i]/g.tot*100).toFixed(0)+' %',fix=((g.cnt[0]+g.cnt[1])/g.tot*100),bad=g.gaps.filter(q=>q.min<=1).length;
  showM('UWB coverage report',pl(fix>=97?'pp':fix>=90?'pw':'pf',fix.toFixed(0)+' % positioned'),
    '<div class="bn'+(g.gaps.length?' bad':'')+'"><b>'+(g.gaps.length?g.gaps.length+' gap area'+(g.gaps.length>1?'s':'')+' where tags cannot get a reliable 2D fix'+(bad?', '+bad+' with no fix at all':'')+'.':'Full floor coverage.')+'</b> '+(UWA.length-WA.uwbOff.size)+' of '+UWA.length+' anchors online. A 2D fix needs 3 anchors in view and a precise fix needs 4. Metal racking, dry cabinets and the cage mesh weaken the signal.</div>'+
    gridH([['Precise, 4+ anchors',pc(0)],['Fix, 3 anchors',pc(1)],['Weak, 2 anchors',pc(2)],['Gap, 0 to 1 anchors',pc(3)],['Floor area',g.tot+' m\u00b2'],['Anchor range',UWR/10+' m line of sight']])+
    '<div><h4>Gap areas</h4>'+(g.gaps.length?tbH(['Gap','Zone','Size','Anchors in view','Suggested fix'],g.gaps.map(q=>trH([q.n,q.zone,q.area+' m\u00b2',q.min<=1?pl('pf',q.min+' (no fix)'):pl('pw','2 (weak)'),'Add an anchor near '+(q.cx/10).toFixed(0)+' m, '+(q.cy/10).toFixed(0)+' m'+(q.zone==='Main storage'?' on the rack end or ceiling above the aisle':'')]))):'<div class="sub">No gaps.</div>')+'</div>'+
    '<div><h4>Anchors</h4>'+tbH(['Anchor','Zone','Position','Status','Area reached',''],UWA.map(a=>{const off=WA.uwbOff.has(a[0]);return trH([a[0],uwbZone(a[1],a[2]),(a[1]/10).toFixed(0)+' m, '+(a[2]/10).toFixed(0)+' m',off?pl('pf','Offline'):pl('pp','Online'),off?'-':(g.cov[a[0]]||0)+' m\u00b2','<button data-uwb="'+a[0]+'">'+(off?'Restore':'Take offline')+'</button>'])}))+'</div>',
    '<button id="wmU2">'+(WA.on.uwb?'Hide':'Show')+' UWB overlay</button><button id="mc">Close</button>');
  $('#dlg').className='dlg xl';$('#mc').onclick=closeM;$('#wmU2').onclick=()=>{WA.on.uwb=!WA.on.uwb;closeM();wmOvSync()};
  document.querySelectorAll('#dlg [data-uwb]').forEach(b=>b.onclick=()=>uwbToggle(b.dataset.uwb,true))}
function uwbToggle(id,rep){const off=WA.uwbOff.has(id);if(off)WA.uwbOff.delete(id);else WA.uwbOff.add(id);const g=uwbGrid();
  scAlert(off?'info':'warn','UWB anchor '+id+(off?' restored':' offline')+', '+g.gaps.length+' coverage gap'+(g.gaps.length===1?'':'s')+' on the floor');wmHud();if(rep)uwbReport()}

