import math,sys
A=[['U-01',10,12],['U-02',150,12],['U-03',330,14],['U-04',520,14],['U-05',690,14],['U-06',770,118],['U-07',770,300],['U-08',700,404],['U-09',470,404],['U-10',250,404],['U-11',10,240],['U-12',10,400],['U-13',268,153],['U-14',470,153],['U-15',164,300],['U-16',584,236]]
def run(k,kc,kq,R,off=()):
  O=[(182,40,380,40,k),(182,102,380,40,k),(182,164,380,40,k),(182,226,380,40,k),(602,36,170,56,kc),(594,126,184,100,kq)]
  W,H=78,41;L=[0]*(W*H)
  for j in range(H):
    for i in range(W):
      x,y=i*10+5,j*10+5;n=0
      for a in A:
        if a[0] in off: continue
        dx,dy=x-a[1],y-a[2];d=math.hypot(dx,dy)
        if d>R: continue
        m=math.ceil(d/4);pen=0
        for t in range(1,m):
          px,py=a[1]+dx*t/m,a[2]+dy*t/m
          for o in O:
            if o[0]<=px<=o[0]+o[2] and o[1]<=py<=o[1]+o[3]: pen+=d/m*o[4];break
        if d+pen<R:n+=1
      L[j*W+i]=n
  # gaps
  seen=set();gaps=[]
  for s in range(W*H):
    if s in seen or L[s]>=3: continue
    st=[s];seen.add(s);c=[]
    while st:
      p=st.pop();c.append(p);i,j=p%W,p//W
      for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
        q=b*W+a
        if 0<=a<W and 0<=b<H and q not in seen and L[q]<3: seen.add(q);st.append(q)
    if len(c)>=3: gaps.append((len(c),round(sum(p%W for p in c)/len(c)),round(sum(p//W for p in c)/len(c)),min(L[p] for p in c)))
  cnt=[sum(1 for v in L if v>=4),sum(1 for v in L if v==3),sum(1 for v in L if v==2),sum(1 for v in L if v<2)]
  print(k,kc,kq,R,off,cnt,sorted(gaps,reverse=True))
for a in sys.argv[1:]:
  p=a.split(',');run(float(p[0]),float(p[1]),float(p[2]),float(p[3]),tuple(p[4:]))
