import AppKit
import CoreText

let PPI: CGFloat = 150
let H = 480

func font(_ name: String, _ size: CGFloat) -> CTFont { CTFontCreateWithName(name as CFString, size, nil) }
func line(_ s: String, _ f: CTFont, _ kern: CGFloat) -> CTLine {
  let a = NSAttributedString(string: s, attributes: [.font: f, .kern: kern, .foregroundColor: NSColor.white])
  return CTLineCreateWithAttributedString(a)
}
func width(_ l: CTLine) -> CGFloat { CGFloat(CTLineGetTypographicBounds(l, nil, nil, nil)) - 0 }

let word = line("NOVASIL", font("AvenirNext-Bold", 172), 14)
let tag = line("SEMICONDUCTOR", font("AvenirNext-Medium", 50), 21.5)
let textX: CGFloat = 500
let W = Int(textX + max(width(word) - 14, width(tag) - 21.5) + 48)

func draw(_ ctx: CGContext, background: CGColor?) {
  if let bg = background { ctx.setFillColor(bg); ctx.fill(CGRect(x: 0, y: 0, width: W, height: H)) }
  ctx.saveGState()
  ctx.beginTransparencyLayer(auxiliaryInfo: nil)
  let white = CGColor(red: 1, green: 1, blue: 1, alpha: 1)
  ctx.setFillColor(white); ctx.setStrokeColor(white)

  // Chip package outline
  let body = CGRect(x: 90, y: 90, width: 300, height: 300)
  ctx.setLineWidth(18)
  ctx.addPath(CGPath(roundedRect: body.insetBy(dx: 9, dy: 9), cornerWidth: 26, cornerHeight: 26, transform: nil))
  ctx.strokePath()

  // Pins, five per side
  let pinLen: CGFloat = 46, pinW: CGFloat = 18
  for i in 0..<5 {
    let c = 140 + CGFloat(i) * 50
    for r in [CGRect(x: c - pinW / 2, y: body.maxY + 10, width: pinW, height: pinLen),
              CGRect(x: c - pinW / 2, y: body.minY - 10 - pinLen, width: pinW, height: pinLen),
              CGRect(x: body.minX - 10 - pinLen, y: c - pinW / 2, width: pinLen, height: pinW),
              CGRect(x: body.maxX + 10, y: c - pinW / 2, width: pinLen, height: pinW)] {
      ctx.addPath(CGPath(roundedRect: r, cornerWidth: 4, cornerHeight: 4, transform: nil)); ctx.fillPath()
    }
  }

  // Die
  ctx.addPath(CGPath(roundedRect: CGRect(x: 142, y: 142, width: 196, height: 196), cornerWidth: 14, cornerHeight: 14, transform: nil))
  ctx.fillPath()

  // "N" circuit trace knocked out of the die, with via rings at each end
  let a = CGPoint(x: 188, y: 186), b = CGPoint(x: 188, y: 294), c = CGPoint(x: 292, y: 186), d = CGPoint(x: 292, y: 294)
  ctx.setBlendMode(.clear)
  ctx.setLineWidth(17); ctx.setLineCap(.round); ctx.setLineJoin(.round)
  ctx.move(to: CGPoint(x: a.x, y: a.y + 14)); ctx.addLine(to: b); ctx.addLine(to: c); ctx.addLine(to: CGPoint(x: d.x, y: d.y - 14))
  ctx.strokePath()
  for p in [a, d] { ctx.fillEllipse(in: CGRect(x: p.x - 19, y: p.y - 19, width: 38, height: 38)) }
  ctx.setBlendMode(.normal)
  for p in [a, d] { ctx.fillEllipse(in: CGRect(x: p.x - 7.5, y: p.y - 7.5, width: 15, height: 15)) }

  // Divider and wordmark
  ctx.fill(CGRect(x: 458, y: 110, width: 4, height: 260))
  ctx.textPosition = CGPoint(x: textX, y: 214); CTLineDraw(word, ctx)
  ctx.textPosition = CGPoint(x: textX + 4, y: 128); CTLineDraw(tag, ctx)

  ctx.endTransparencyLayer()
  ctx.restoreGState()
}

func save(_ path: String, background: CGColor?) {
  let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: W, pixelsHigh: H, bitsPerSample: 8, samplesPerPixel: 4,
                             hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)!
  let g = NSGraphicsContext(bitmapImageRep: rep)!
  g.cgContext.clear(CGRect(x: 0, y: 0, width: W, height: H))
  draw(g.cgContext, background: background)
  g.flushGraphics()
  rep.size = NSSize(width: CGFloat(W) * 72 / PPI, height: CGFloat(H) * 72 / PPI)
  try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: path))
}

