// 1. Lumina Silicon: halftone wafer lit from the upper right, stacked layout
do {
  let W = 900, H = 1000, cx: CGFloat = 450, cy: CGFloat = 615, R: CGFloat = 250
  save("lumina-silicon-logo", W, H) { ctx in
    ctx.setLineWidth(14); ctx.strokeEllipse(in: CGRect(x: cx - R, y: cy - R, width: 2 * R, height: 2 * R))
    let pitch: CGFloat = 31, inner = R - 30, light = CGPoint(x: cx + R * 0.5, y: cy + R * 0.5)
    var gy = cy - inner
    while gy <= cy + inner {
