    let mid = { (p: CGPoint, q: CGPoint) in CGPoint(x: (p.x + q.x) / 2, y: (p.y + q.y) / 2) }
    let faces = [mid(c, v[0]), mid(c, v[2]), mid(c, v[4])].map { p in mid(p, p) }
