      ctx.move(to: CGPoint(x: x, y: y - h * k)); ctx.addLine(to: CGPoint(x: x, y: y - h * k - th)); ctx.strokePath()
      if i == layers.count - 1 {
        for u in stride(from: -1.0, through: 1.0, by: 1.0) { for vv in stride(from: -1.0, through: 1.0, by: 1.0) {
          let px = x + CGFloat(u - vv) * a * k * 0.3, py = y + CGFloat(u + vv) * h * k * 0.3
          ctx.fillEllipse(in: CGRect(x: px - 12, y: py - 7, width: 24, height: 14))
        } }
      }
      ctx.setBlendMode(.normal)
    }
    text(ctx, w, 474, 210); text(ctx, t, 484, 140)
    ctx.fill(CGRect(x: 484, y: 192, width: 70, height: 5))
  }
}

