func wafer(_ ctx: CGContext, _ cx: CGFloat, _ cy: CGFloat, _ R: CGFloat, coarse: CGFloat = 1, ring: CGFloat = 1) {
  let k = R / 250
  ctx.setLineWidth(14 * k * ring); ctx.strokeEllipse(in: CGRect(x: cx - R, y: cy - R, width: 2 * R, height: 2 * R))
  let pitch = 31 * k * coarse, inner = R - 30 * k * ring, light = CGPoint(x: cx + R * 0.5, y: cy + R * 0.5)
  let n = Int(inner / pitch)
  for i in -n...n { for j in -n...n {
    let px = cx + CGFloat(i) * pitch, py = cy + CGFloat(j) * pitch
    guard hypot(abs(px - cx) + pitch * 0.42, abs(py - cy) + pitch * 0.42) < inner else { continue }
    let t = min(1, hypot(px - light.x, py - light.y) / (1.55 * R))
    let s = max(3.5 * k * coarse, pitch * 0.86 * (1 - 0.93 * pow(t, 0.85)))
    ctx.addPath(CGPath(roundedRect: CGRect(x: px - s / 2, y: py - s / 2, width: s, height: s), cornerWidth: s * 0.2, cornerHeight: s * 0.2, transform: nil))
    ctx.fillPath()
  } }
  let nw = 20 * k * ring
  ctx.setBlendMode(.clear)
  ctx.move(to: CGPoint(x: cx - nw, y: cy - R - nw * 0.6)); ctx.addLine(to: CGPoint(x: cx, y: cy - R + nw * 0.8)); ctx.addLine(to: CGPoint(x: cx + nw, y: cy - R - nw * 0.6)); ctx.fillPath()
