ctx.translateBy(x: 0, y: CGFloat(H)); ctx.scaleBy(x: 1, y: -1)   // top-left origin

func text(_ s: String, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat, _ color: CGColor, bold: Bool = false, center: Bool = false, width: CGFloat = 0) {
  let font = NSFont(name: bold ? "HelveticaNeue-Bold" : "HelveticaNeue", size: size)!
  let p = NSMutableParagraphStyle(); p.alignment = center ? .center : .left; p.lineSpacing = 2
  let a = NSAttributedString(string: s, attributes: [.font: font, .foregroundColor: NSColor(cgColor: color)!, .paragraphStyle: p])
  NSGraphicsContext.saveGraphicsState()
  let flipped = NSGraphicsContext(cgContext: ctx, flipped: true); NSGraphicsContext.current = flipped
  let w = width > 0 ? width : a.size().width + 4
  a.draw(with: NSRect(x: center && width == 0 ? x - w / 2 : x, y: y, width: w, height: 400), options: [.usesLineFragmentOrigin])
  NSGraphicsContext.restoreGraphicsState()
}
func box(_ r: CGRect, fill: CGColor, stroke: CGColor? = nil, radius: CGFloat = 10, lw: CGFloat = 2) {
  let p = CGPath(roundedRect: r, cornerWidth: radius, cornerHeight: radius, transform: nil)
  ctx.addPath(p); ctx.setFillColor(fill); ctx.fillPath()
  if let s = stroke { ctx.addPath(p); ctx.setStrokeColor(s); ctx.setLineWidth(lw); ctx.strokePath() }
}
func arrow(_ a: CGPoint, _ b: CGPoint, _ c: CGColor = MUTED, dashed: Bool = false) {
  ctx.setStrokeColor(c); ctx.setLineWidth(3)
  if dashed { ctx.setLineDash(phase: 0, lengths: [10, 7]) }
  ctx.move(to: a); ctx.addLine(to: b); ctx.strokePath(); ctx.setLineDash(phase: 0, lengths: [])
  let ang = atan2(b.y - a.y, b.x - a.x), L: CGFloat = 16
  ctx.move(to: b); ctx.addLine(to: CGPoint(x: b.x - L * cos(ang - 0.45), y: b.y - L * sin(ang - 0.45)))
  ctx.addLine(to: CGPoint(x: b.x - L * cos(ang + 0.45), y: b.y - L * sin(ang + 0.45))); ctx.closePath()
  ctx.setFillColor(c); ctx.fillPath()
}
func column(_ x: CGFloat, _ w: CGFloat, _ title: String, _ sub: String) {
  box(CGRect(x: x, y: 110, width: w, height: 1150), fill: TINT, stroke: LINE, radius: 14)
  box(CGRect(x: x, y: 110, width: w, height: 70), fill: NAVY, radius: 14)
  ctx.setFillColor(NAVY); ctx.fill(CGRect(x: x, y: 150, width: w, height: 30))
