}
func item(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ title: String, _ body: String, accent: CGColor = BLUE) {
  box(CGRect(x: x, y: y, width: w, height: h), fill: CGColor(red: 1, green: 1, blue: 1, alpha: 1), stroke: LINE, radius: 8)
